@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink:#17202a; --muted:#6e7985; --line:#e4e9ee; --accent:#635bff; --accent-dark:#4c45d8; --soft:#f5f6ff; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); font-family:'DM Sans',sans-serif; background:radial-gradient(circle at 15% 10%,#e9e7ff 0,transparent 32%),linear-gradient(135deg,#f7f9fc,#eef2f7); }
.page-shell { min-height:100vh; display:flex; align-items:center; justify-content:center; padding:42px 18px; }
.quiz-card { width:min(760px,100%); background:rgba(255,255,255,.94); border:1px solid rgba(255,255,255,.8); border-radius:24px; box-shadow:0 24px 70px rgba(35,46,70,.14); overflow:hidden; }
.quiz-header { padding:42px 48px 30px; border-bottom:1px solid var(--line); }
.eyebrow { color:var(--accent); font-size:12px; font-weight:700; letter-spacing:.14em; text-transform:uppercase; margin-bottom:12px; }
h1 { font-family:'Space Grotesk',sans-serif; font-size:clamp(30px,5vw,44px); line-height:1.05; letter-spacing:-.04em; margin:0 0 12px; }
.quiz-header p { color:var(--muted); margin:0; font-size:16px; }
.questions { padding:8px 48px 10px; }
.question { border:0; border-bottom:1px solid var(--line); padding:27px 0 29px; margin:0; min-width:0; }
.question:last-child { border-bottom:0; }
legend { width:100%; display:flex; align-items:flex-start; gap:16px; padding:0; font-family:'Space Grotesk',sans-serif; font-size:18px; font-weight:600; line-height:1.4; }
.question-number { flex:none; color:var(--accent); font-size:12px; letter-spacing:.1em; padding-top:5px; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin:19px 0 0 36px; }
.option { display:flex; align-items:center; gap:9px; border:1px solid var(--line); border-radius:10px; padding:12px 13px; color:#4f5a66; font-size:14px; cursor:pointer; transition:.18s ease; }
.option:hover { border-color:#aaa6ff; background:var(--soft); color:var(--ink); transform:translateY(-1px); }
.option input { position:absolute; opacity:0; pointer-events:none; }
.custom-radio { width:15px; height:15px; border:1.5px solid #b9c1ca; border-radius:50%; flex:none; position:relative; }
.option:has(input:checked) { border-color:var(--accent); background:var(--soft); color:var(--ink); box-shadow:0 0 0 2px rgba(99,91,255,.1); }
.option input:checked + .custom-radio { border-color:var(--accent); }
.option input:checked + .custom-radio:after { content:''; position:absolute; inset:3px; border-radius:50%; background:var(--accent); }
.quiz-footer { display:flex; align-items:center; justify-content:space-between; gap:20px; background:#fafbfc; padding:25px 48px; }
button { border:0; border-radius:11px; background:var(--accent); color:#fff; padding:14px 20px; font:600 15px 'DM Sans',sans-serif; cursor:pointer; box-shadow:0 8px 18px rgba(99,91,255,.24); transition:.18s ease; }
button:hover { background:var(--accent-dark); transform:translateY(-1px); }
button span { font-size:20px; vertical-align:-1px; margin-left:8px; }
.result { text-align:right; }
.result-label { display:block; color:var(--muted); font-size:11px; text-transform:uppercase; letter-spacing:.1em; font-weight:700; }
.result strong { font:700 28px 'Space Grotesk',sans-serif; color:var(--accent); }
.out-of { color:var(--muted); font-size:14px; }
.message { min-height:0; color:#c44b4b; font-size:13px; margin:0; padding:0 48px 18px; }
@media (max-width:600px) { .quiz-header,.questions { padding-left:24px; padding-right:24px; } .quiz-footer { padding:22px 24px; } .options { grid-template-columns:1fr; margin-left:0; } legend { font-size:16px; } }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const message = document.getElementById('message');
const answers = { q1: 'mars', q2: 'pacific', q3: 'html' };

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const data = new FormData(form);
  const unanswered = ['q1', 'q2', 'q3'].filter((name) => !data.get(name));

  if (unanswered.length) {
    message.textContent = `Please answer ${unanswered.length === 1 ? 'the remaining question' : 'all three questions'} before submitting.`;
    return;
  }

  let score = 0;
  Object.keys(answers).forEach((question) => {
    if (data.get(question) === answers[question]) score += 1;
  });
  scoreElement.textContent = score;
  scoreElement.dataset.score = String(score);
  message.textContent = score === 3 ? 'Perfect score — excellent work!' : 'Your result is ready. You can change your answers and submit again.';
});

form.addEventListener('change', () => {
  message.textContent = '';
});

